-- Create worker_runs: one row = one scheduled run of the price worker (an event).
-- Used for:
--   - restart safety: each run is tied to a unique schedule slot, so a crashed
--     worker that restarts reuses the SAME run (and the same run id)
--   - the budget guard: sum requests_used since the monthly JustTCG reset
--   - debugging/analytics: status, timing, and errors for every run
-- Referenced later by sent_pushes (unique user + run) and run_cards_log.

-- migrate:up

create table worker_runs (
  -- Auto-incrementing number (1, 2, 3…) generated by Postgres. Readable in logs ("run #42").
  -- Runs are internal (never exposed in public URLs), so a guessable number is fine here.
  id             bigint generated always as identity primary key,

  -- The scheduled time this run belongs to, rounded down to the schedule
  -- (e.g. 2026-11-03 14:00 UTC), NOT the moment it actually started.
  --   unique → a restart in the same window finds the existing row and reuses it,
  --            so (user, run) stays stable and pushes are never sent twice.
  -- The unique constraint also gives us an index, which the budget guard's
  -- "runs since the reset date" query can use.
  slot           timestamptz not null unique,

  -- Only these three values are allowed. A check constraint rejects typos like 'succeded'.
  -- A row stuck at 'running' for over an hour = a run that crashed hard.
  status         text not null default 'running'
                   check (status in ('running', 'succeeded', 'failed')),

  started_at     timestamptz not null default now(),

  -- Empty while running. Set when the run succeeds or fails.
  finished_at    timestamptz,

  -- Why a run failed (e.g. 'JustTCG returned 429'). Empty if it succeeded.
  error          text,

  -- JustTCG calls made by this run, incremented after every call (retries included).
  -- The budget guard sums this since the monthly reset. Counts are never reset; the window moves.
  requests_used  integer not null default 0 check (requests_used >= 0)
);

-- ─── Lock the table to direct access (ADR-006) ──────────────────────
-- Only the worker (service-role key) touches this table. Admin-only analytics.
alter table worker_runs enable row level security;
revoke all on worker_runs from anon, authenticated;

-- migrate:down

drop table worker_runs;
